import ast
import json
from fractions import Fraction

expressions = {
    "A": """not ((not not (5 - (-2 / 3) > 6) or not not not (7 - (-5 / 4) is greater than 8)) or ((5 - (-5 / 1) is greater than -6) or (max(9, -3, -6, -1) - min(9, -3, -6, -1) is greater than 3))) and (not (not (max(6, 7, 9, 4) - min(6, 7, 9, 4) <= 6) or (8 * 10 > 8)) and (not not (-6 - (7 / 6) is less than or equal to 6) or not not not (False)))""",
    "B": """not not not (not not ((not not not (not (not (not not not (not (not not not (The capital of Iran is Tehran.) and not not (True)) or (-9 * 9 > 3)) and not not (9 * 4 + 4 * 8 is greater than -3 * 8)) and (The capital of Azerbaijan is Ganja.)) and (max(-6, 2, -1, 4) - min(-6, 2, -1, 4) is greater than 5)) and not not (10 * -5 + -2 * 8 > -5 * 5)) or (-7 - (3 / 2) is less than or equal to -7)) or not not not (True)) and not not (-1 * 9 + -5 * -5 is less than or equal to -3 * 3)""",
    "C": """not not not (not (not (max(9, -1, 6, 9) - min(9, -1, 6, 9) is greater than 6) and (The capital of UAE is Dubai.)) and (not (-1 - (-10 / 5) > 9) or (10 * 7 + 1 * -5 is greater than -2 * 3))) and not not (not not (not (4 * 4 + -4 * 2 > -9 * -8) and (-3 * -4 + 1 * -7 <= -9 * -2)) or not not not (not not not (max(-2, -10, 2, -2) - min(-2, -10, 2, -2) is greater than 10) and not not (3 * -10 > -9)))""",
    "D": """not (not not (not not (not not (1 * -9 + 2 * -1 <= -1 * 3) or not not not (max(10, 5, 1, 10) - min(10, 5, 1, 10) is greater than 7)) or not not not ((False) or (-3 * -9 > 8))) or not not not (not not (not not not (The capital of Armenia is Yerevan.) and not not (False)) or not not not (not (-3 - (-4 / 4) is less than or equal to 1) and (max(6, -5, 8, 7) - min(6, -5, 8, 7) is greater than 8)))) or (not not not (not not (not (-5 * 3 + -5 * 8 <= -3 * 6) and (-3 * -6 > 1)) or not not not (not (10 - (-6 / 1) is greater than 10) and (The capital of Armenia is Yerevan.))) and not not (((9 * 4 + 4 * 6 is less than or equal to 10 * -8) and (False)) and ((-9 - (10 / -7) is greater than -10) or (-2 * -3 + 6 * 4 is greater than -2 * 4))))""",
    "E": """not not (not (not not (not not (-6 * 7 is less than or equal to -1) or not not not (True)) or not not not (not not not (False) and not not (9 - (-4 / -6) <= -4))) and (not not not (not (10 * 9 + -10 * 7 > -3 * -7) and (3 * -3 + -9 * -2 is greater than -9 * 5)) and not not (not (The capital of Armenia is Gyumri.) or (False)))) or not not not (not (not not (not (10 - (-8 / 2) <= 4) and (True)) or not not not (not not (True) or not not not (The capital of Norway is Oslo.))) or (not not not (not not not (-7 * -1 + -2 * 8 is greater than 9 * -10) and not not (3 * -2 + -4 * 5 <= 4 * 6)) and not not (not (-8 - (4 / -9) is less than or equal to 4) and (max(9, -8, -7, 9) - min(9, -8, -7, 9) is greater than 9))))"""
}

capitals = {
    "Iran": "Tehran",
    "Azerbaijan": "Baku",
    "UAE": "Abu Dhabi",
    "Armenia": "Yerevan",
    "Norway": "Oslo",
}

claims = [
    ("Iran", "Tehran"),
    ("Azerbaijan", "Ganja"),
    ("UAE", "Dubai"),
    ("Armenia", "Yerevan"),
    ("Armenia", "Gyumri"),
    ("Norway", "Oslo"),
]


def translate(text):
    for country, city in claims:
        statement = "The capital of " + country + " is " + city + "."
        text = text.replace(statement, str(capitals[country] == city))
    return (text.replace("is less than or equal to", "<=")
                .replace("is greater than", ">"))


def compute(node):
    if isinstance(node, ast.Expression):
        return compute(node.body)

    if isinstance(node, ast.Constant):
        if type(node.value) in (int, bool):
            return node.value
        raise ValueError("Unsupported constant")

    if isinstance(node, ast.UnaryOp):
        value = compute(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        raise ValueError("Unsupported unary operator")

    if isinstance(node, ast.BoolOp):
        values = [bool(compute(item)) for item in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError("Unsupported Boolean operator")

    if isinstance(node, ast.BinOp):
        left, right = compute(node.left), compute(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return Fraction(left) / Fraction(right)
        raise ValueError("Unsupported arithmetic operator")

    if isinstance(node, ast.Compare):
        left = compute(node.left)
        outcomes = []
        for operator, operand in zip(node.ops, node.comparators):
            right = compute(operand)
            if isinstance(operator, ast.Gt):
                outcomes.append(left > right)
            elif isinstance(operator, ast.LtE):
                outcomes.append(left <= right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(outcomes)

    if isinstance(node, ast.Call):
        if (not isinstance(node.func, ast.Name)
                or node.func.id not in ("max", "min")
                or node.keywords):
            raise ValueError("Unsupported function")
        values = [compute(argument) for argument in node.args]
        return max(values) if node.func.id == "max" else min(values)

    raise ValueError("Unsupported syntax")


try:
    results = {
        label: compute(ast.parse(translate(text), mode="eval"))
        for label, text in expressions.items()
    }
    winners = [label for label, value in results.items() if value is True]
    if len(winners) != 1 or any(type(v) is not bool for v in results.values()):
        print("UNSUPPORTED")
    else:
        print(json.dumps({
            "final_answer": "(" + winners[0] + ")",
            "evidence": {
                "values": results,
                "arithmetic": "exact rational",
                "actual_capitals": capitals
            }
        }, separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
